    <title>Pravilnik i pomoć · Putni nalozi</title>
    <style>
        :root { --blue:#007aff; --text:#172033; --muted:#637083; --line:#e4e8ef; --bg:#f5f7fb; } *{box-sizing:border-box} body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif} main{max-width:780px;margin:0 auto;padding:48px 20px 64px}.brand,a{color:var(--blue);text-decoration:none}.brand{font-weight:800;font-size:15px}h1{font-size:34px;letter-spacing:-.7px;margin:28px 0 8px}p{color:var(--muted);line-height:1.6}section{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px 24px;margin-top:12px}h2{font-size:18px;margin:0 0 8px}ol{padding-left:21px;margin:0}li{color:#344054;line-height:1.7}footer{display:flex;gap:14px;flex-wrap:wrap;margin-top:22px;font-size:14px}
    </style>
